const char* link_path = "symlink_to_target";
uid_t new_owner = 1001;
gid_t new_group = 100;

// lchown: Changes owner/group of the link,
// does not dereference the link.
// Requires EPERM/CAP_CHOWN unless changing only group
// to one the process is a member of.
int ret = lchown(link_path, new_owner, new_group);

if (ret == -1) {
    // Check errno for EPERM (not privileged), EACCES, ENOENT
    perror("lchown error");
}
